source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width/full-height uniform rows and columns are the panel dividers.
    divider_rows = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    row_ranges = []
    start = 0
    for r in divider_rows + [h]:
        if start < r:
            row_ranges.append((start, r))
        start = r + 1
    col_ranges = []
    start = 0
    for c in divider_cols + [w]:
        if start < c:
            col_ranges.append((start, c))
        start = c + 1

    # The nonempty panel outside the left-hand color examples gives the motif.
    motif = None
    for ri, (r0, r1) in enumerate(row_ranges):
        for ci, (c0, c1) in enumerate(col_ranges):
            if ci == 0:
                continue
            mask = [[grid[r][c] != 0 for c in range(c0, c1)] for r in range(r0, r1)]
            if any(any(row) for row in mask):
                motif = mask
                break
        if motif is not None:
            break

    # Each row's example color is shown in its first panel.
    colors = []
    for r0, r1 in row_ranges:
        counts = {}
        for r in range(r0, r1):
            for c in range(col_ranges[0][0], col_ranges[0][1]):
                color = grid[r][c]
                if color != 0:
                    counts[color] = counts.get(color, 0) + 1
        colors.append(max(counts, key=counts.get))

    out = [row[:] for row in grid]
    for ri, (r0, r1) in enumerate(row_ranges):
        for c0, c1 in col_ranges:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    out[r][c] = colors[ri] if motif[r-r0][c-c0] else 0
    return out
'''
